import { describe, expect, it } from 'vitest';
import { creditProblems, identityProblem } from './credit.mjs';

describe('creditProblems', () => {
  it.each([
    'Co-Authored-By: Claude <noreply@anthropic.com>',
    'Co-authored-by: Claude Opus 5.5 <noreply@anthropic.com>',
    'co-authored-by: codex <codex@openai.com>',
    'Co-Authored-By: github-actions[bot] <41898282+github-actions[bot]@users.noreply.github.com>',
    '🤖 Generated with [Claude Code](https://claude.com/claude-code)',
    'Generated with Claude Code',
    'Generated by GPT-6',
    'Generated by an AI agent',
  ])('rejects %s', (line) => {
    expect(creditProblems(`Fix the trainer\n\n${line}`)).toEqual([line]);
  });

  it.each([
    'Generated with Vite for the main bundle',
    'Explain the detail in the main panel',
    'Co-Authored-By: Sam Rivera <sam@example.com>',
    'Add a 🤖 icon to the robot list',
    'Make the generated mesh smaller',
  ])('accepts %s', (line) => {
    expect(creditProblems(`Fix the trainer\n\n${line}`)).toEqual([]);
  });

  it('ignores comment lines git strips', () => {
    expect(creditProblems('Fix it\n# Co-Authored-By: Claude <noreply@anthropic.com>')).toEqual([]);
  });
});

describe('identityProblem', () => {
  it.each([
    { name: 'Claude', email: 'noreply@anthropic.com' },
    { name: 'Claude Code', email: 'someone@example.com' },
    { name: 'github-actions[bot]', email: '41898282+github-actions[bot]@users.noreply.github.com' },
    { name: 'Codex', email: 'codex@openai.com' },
  ])('rejects $name', (who) => {
    expect(identityProblem(who)).not.toBeNull();
  });

  it.each([
    { name: 'Jamel Hammoud', email: 'jamel@example.com' },
    { name: 'Claude Monet', email: 'claude@example.com' },
  ])('accepts $name', (who) => {
    expect(identityProblem(who)).toBeNull();
  });
});
